func encryptData(key, data []byte) ([]byte, []byte, []byte, error) {
	// Choose AES algorithm (block size 16 bytes)
	aesBlockSize := aes.BlockSize
	aesKeyLen := aesBlockSize * 4 // 64 bytes for AES-256

	// Use the prefix of the key for AES-256
	if len(key) < aesKeyLen {
		return nil, nil, nil, errors.New("key is too short for AES-256")
	}
	aesKey := key[:aesKeyLen]

	// Generate a random IV (16 bytes for AES)
	iv := make([]byte, aesBlockSize)
	if _, err := rand.Read(iv); err != nil {
		return nil, nil, nil, err
	}

	// Create AES cipher
	block, err := aes.NewCipher(aesKey)
	if err != nil {
		return nil, nil, nil, err
	}

	// Create a new CBC mode encryptor
	cbc := cipher.NewCBCEncrypter(block, iv)

	// Pad the data to be a multiple of the block size
	paddedData := make([]byte, len(data))
	copy(paddedData, data)
	paddedData = padPKCS7(padded, aesBlockSize)

	// Encrypt the data
	encryptedData := make([]byte, len(paddedData))
	cbc.CryptBlocks(encryptedData, paddedData)

	return encryptedData, iv, aesKey, nil
}

func padPKCS7(data []byte, blockSize int) []byte {
	// Calculate how much padding is needed
	padding := blockSize - (len(data) % blockSize)
	if padding == 0 {
		padding = blockSize
	}
	pad := bytes.Repeat([]byte{byte(padding)}, padding)
	return append(data, pad...)
}
